mapper.select:
SELECT encode(text_hash, 'hex') AS hash, embedding::text AS vector FROM signature_vectors
 WHERE kb_id = #{kbId} AND model = #{model}
   AND text_hash = ANY(SELECT decode(h, 'hex') FROM unnest(#{hashes}::text[]) AS t(h))

mapper.delete:
DELETE FROM signature_vectors
 WHERE kb_id = #{kbId} AND (model <> #{model}
        OR NOT (text_hash = ANY(SELECT decode(h, 'hex') FROM unnest(#{keep}::text[]) AS t(h))))
